-- Recipes part 4/4: insert-only.
do $seed$
declare d jsonb := '[{"slug":"chana-chaat","name":"Chana Chaat","description":"Chickpeas tossed with onion, tomato, cucumber, chutney and chaat masala.","category":"Snacks","cuisine":"Pakistani","minutes":15,"servings":4,"taste":{"sweet":3,"salty":5,"sour":7,"spicy":4},"lines":[["Kabuli Chickpeas (Chana)",400,"2 cups, boiled"],["Onion",80,"1 small, chopped"],["Tomato",100,"1, chopped"],["Cucumber",100,"1, diced"],["Green Chilli",5,"1, chopped"],["Tamarind Chutney",40,"3 tbsp"],["Lemon",15,"juice of 1/2"],["Chaat Masala",5,"1 1/2 tsp"],["Fresh Coriander",8,"chopped"],["Salt",3,"1/2 tsp"]],"steps":["Mix the chickpeas with the vegetables.","Add chutney, lemon, chaat masala and salt and toss well.","Garnish with coriander and serve straight away."]},{"slug":"aloo-tikki","name":"Aloo Tikki","description":"Crisp pan-fried potato patties with herbs and spices.","category":"Snacks","cuisine":"Pakistani","minutes":35,"servings":4,"taste":{"sweet":1,"salty":5,"sour":3,"spicy":4},"lines":[["Potato",500,"4, boiled and mashed"],["Corn Flour",20,"2 tbsp"],["Green Chilli",10,"2, chopped"],["Fresh Coriander",10,"chopped"],["Cumin (Zeera)",2,"1/2 tsp, roasted"],["Chaat Masala",3,"1 tsp"],["Red Chilli Flakes (Kuti Lal Mirch)",2,"1/2 tsp"],["Cooking Oil",60,"for shallow frying"],["Salt",5,"1 tsp"]],"steps":["Mix the mashed potato with corn flour, herbs and spices.","Shape into flat patties.","Shallow-fry on medium heat until golden and crisp on both sides.","Serve with tamarind and mint chutney."]},{"slug":"chicken-paratha-roll","name":"Chicken Paratha Roll","description":"Spicy chicken tikka strips wrapped in a crisp paratha with garlic sauce and onions.","category":"Snacks","cuisine":"Pakistani","minutes":40,"servings":4,"taste":{"sweet":2,"salty":6,"sour":4,"spicy":6},"lines":[["Chicken Boneless (Boti)",400,"400 g, strips"],["Wheat Flour (Atta)",300,"2 cups, for 4 parathas"],["Yogurt (Dahi)",60,"1/4 cup"],["Tikka Masala",15,"1 1/2 tbsp"],["Garlic Sauce",60,"1/4 cup"],["Onion",100,"1, sliced"],["Mint Chutney",30,"2 tbsp"],["Desi Ghee",40,"for parathas"],["Cooking Oil",20,"1 1/2 tbsp"],["Salt",5,"1 tsp"]],"steps":["Marinate the chicken in yogurt and tikka masala for 30 minutes; stir-fry on high heat until charred.","Knead the atta with water and salt; roll and cook four parathas with ghee.","Spread garlic sauce and mint chutney on each paratha, add chicken and onion.","Roll tightly, wrap the end in paper and serve."]},{"slug":"suji-halwa","name":"Suji Halwa","description":"Semolina roasted in ghee and cooked with sugar syrup, cardamom and nuts.","category":"Desserts","cuisine":"Pakistani","minutes":25,"servings":4,"taste":{"sweet":9,"salty":1,"sour":0,"spicy":0},"lines":[["Semolina (Suji)",150,"3/4 cup"],["Desi Ghee",80,"1/3 cup"],["White Sugar",150,"3/4 cup"],["Green Cardamom (Elaichi)",2,"4, crushed"],["Almonds (Badam)",20,"sliced"],["Raisins (Kishmish)",15,"a handful"]],"steps":["Make a syrup with the sugar, cardamom and 2 cups water.","Roast the suji in ghee on low heat until golden and fragrant (10 minutes).","Carefully pour in the hot syrup, stirring, and cook until it leaves the sides.","Garnish with almonds and raisins."]},{"slug":"zarda","name":"Zarda","description":"Sweet saffron rice with nuts and raisins, served at celebrations.","category":"Desserts","cuisine":"Pakistani","minutes":45,"servings":6,"taste":{"sweet":9,"salty":1,"sour":0,"spicy":0},"lines":[["Basmati Rice",300,"1 1/2 cups, soaked"],["White Sugar",250,"1 1/4 cups"],["Desi Ghee",60,"1/4 cup"],["Green Cardamom (Elaichi)",2,"4"],["Cloves (Laung)",1,"4"],["Saffron (Zafran)",0.3,"a pinch, in milk"],["Almonds (Badam)",25,"sliced"],["Raisins (Kishmish)",25,"a handful"],["Khoya (Mawa)",50,"crumbled, optional"]],"steps":["Boil the rice until 80% cooked and drain.","Heat ghee with cardamom and cloves, add the sugar and 1/2 cup water and stir until it melts.","Fold in the rice, saffron, nuts and raisins.","Cover and steam on the lowest heat for 15 minutes; top with khoya."]},{"slug":"firni","name":"Firni","description":"Chilled ground-rice pudding scented with cardamom and kewra, set in clay bowls.","category":"Desserts","cuisine":"Pakistani","minutes":40,"servings":6,"taste":{"sweet":8,"salty":1,"sour":0,"spicy":0},"lines":[["Milk",1000,"1 litre"],["Rice Flour",60,"1/3 cup"],["White Sugar",120,"2/3 cup"],["Green Cardamom (Elaichi)",2,"4, ground"],["Kewra Water",5,"1 tsp"],["Pistachios (Pista)",15,"chopped"]],"steps":["Mix the rice flour with 1/2 cup cold milk.","Bring the rest of the milk to a boil, stir in the rice flour paste and cook on low heat, stirring, for 15 minutes.","Add sugar and cardamom and cook until thick.","Add kewra, pour into bowls, chill and top with pistachios."]},{"slug":"shahi-tukray","name":"Shahi Tukray","description":"Fried bread soaked in syrup and topped with thick, sweet rabri.","category":"Desserts","cuisine":"Pakistani","minutes":45,"servings":6,"taste":{"sweet":9,"salty":1,"sour":0,"spicy":0},"lines":[["Bread",200,"6 slices, crusts removed"],["Desi Ghee",60,"for frying"],["White Sugar",150,"3/4 cup"],["Milk",750,"3 cups"],["Condensed Milk",100,"1/3 cup"],["Green Cardamom (Elaichi)",2,"4"],["Saffron (Zafran)",0.2,"a pinch"],["Pistachios (Pista)",15,"sliced"],["Almonds (Badam)",15,"sliced"]],"steps":["Cut the bread into triangles and fry golden in ghee.","Make a syrup with 1/2 cup sugar and 1/2 cup water; dip the fried bread briefly.","Reduce the milk with the rest of the sugar, condensed milk, cardamom and saffron to a thick rabri (25 minutes).","Pour the rabri over the bread and garnish with nuts."]},{"slug":"gulab-jamun","name":"Gulab Jamun","description":"Soft milk-powder dumplings fried golden and soaked in cardamom syrup.","category":"Desserts","cuisine":"Pakistani","minutes":50,"servings":6,"taste":{"sweet":10,"salty":1,"sour":0,"spicy":0},"lines":[["Milk Powder",150,"1 1/4 cups"],["Refined Flour (Maida)",40,"1/3 cup"],["Baking Powder",3,"1/2 tsp"],["Desi Ghee",20,"1 1/2 tbsp"],["Milk",80,"1/3 cup, as needed"],["White Sugar",300,"1 1/2 cups"],["Green Cardamom (Elaichi)",2,"4"],["Rose Water (Gulab Jal)",5,"1 tsp"],["Cooking Oil",40,"for frying (about 3 tbsp absorbed)"]],"steps":["Boil the sugar with 1 1/2 cups water and cardamom for 5 minutes; add rose water.","Mix milk powder, maida, baking powder and ghee; add milk to make a soft dough.","Shape into smooth balls and fry on low heat until deep golden.","Drop into the warm syrup and soak for at least 1 hour."]},{"slug":"anda-paratha","name":"Anda Paratha","description":"A crisp whole-wheat paratha cooked with a spiced egg layer inside.","category":"Breakfast","cuisine":"Pakistani","minutes":25,"servings":2,"taste":{"sweet":0,"salty":5,"sour":1,"spicy":3},"lines":[["Wheat Flour (Atta)",200,"1 1/2 cups"],["Eggs",100,"2"],["Onion",40,"1/2, finely chopped"],["Green Chilli",5,"1, chopped"],["Fresh Coriander",5,"chopped"],["Desi Ghee",30,"2 tbsp"],["Salt",4,"3/4 tsp"],["Black Pepper",1,"a pinch"]],"steps":["Knead the atta with water and a pinch of salt; rest for 10 minutes.","Beat the eggs with onion, chilli, coriander, salt and pepper.","Roll a paratha, cook one side, then make a slit, pour in the egg and seal.","Cook both sides with ghee until crisp and golden."]},{"slug":"dalia","name":"Meetha Dalia","description":"Cracked-wheat porridge cooked in milk with jaggery and nuts.","category":"Breakfast","cuisine":"Pakistani","minutes":25,"servings":3,"taste":{"sweet":6,"salty":1,"sour":0,"spicy":0},"lines":[["Cracked Wheat (Dalia)",100,"1/2 cup"],["Milk",600,"2 1/2 cups"],["Jaggery (Gur)",50,"1/4 cup"],["Desi Ghee",10,"2 tsp"],["Green Cardamom (Elaichi)",1,"2, crushed"],["Almonds (Badam)",15,"chopped"],["Raisins (Kishmish)",15,"a handful"]],"steps":["Roast the dalia in ghee for 3 minutes.","Add the milk and cook on low heat, stirring, for 15 minutes until soft.","Stir in jaggery and cardamom and top with nuts and raisins."]},{"slug":"aloo-bhujia","name":"Aloo Bhujia","description":"Thin potato slices stir-fried with cumin, turmeric and green chillies, eaten with paratha.","category":"Breakfast","cuisine":"Pakistani","minutes":25,"servings":4,"taste":{"sweet":1,"salty":5,"sour":2,"spicy":4},"lines":[["Potato",500,"4, thinly sliced"],["Onion",80,"1, sliced"],["Cumin (Zeera)",3,"1 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Red Chilli Flakes (Kuti Lal Mirch)",3,"1 tsp"],["Green Chilli",10,"2"],["Cooking Oil",40,"3 tbsp"],["Salt",6,"1 tsp"],["Fresh Coriander",5,"chopped"]],"steps":["Crackle cumin in oil and fry the onion until soft.","Add the potatoes, spices and salt; cover and cook on low heat for 10 minutes.","Uncover and stir-fry until the potatoes are tender and lightly crisp. Garnish with coriander."]}]'::jsonb; r jsonb; rid bigint; i int; missing text;
begin
select string_agg(distinct l->>0, ', ') into missing from jsonb_array_elements(d) r2, jsonb_array_elements(r2->'lines') l where not exists (select 1 from public.ingredients x where x.name = l->>0);
if missing is not null then raise exception 'Unknown ingredients: %', missing; end if;
for r in select * from jsonb_array_elements(d) loop
insert into public.curated_recipes(slug, name, description, category, cuisine, minutes, servings, taste, status, source) values (r->>'slug', r->>'name', r->>'description', r->>'category', r->>'cuisine', (r->>'minutes')::int, (r->>'servings')::int, r->'taste', 'published', 'curated') on conflict (slug) do nothing returning id into rid;
continue when rid is null;
for i in 0 .. jsonb_array_length(r->'lines') - 1 loop
insert into public.recipe_ingredients(recipe_id, ingredient_id, position, grams, display) select rid, x.id, i + 1, (r->'lines'->i->>1)::numeric, r->'lines'->i->>2 from public.ingredients x where x.name = r->'lines'->i->>0;
end loop;
for i in 0 .. jsonb_array_length(r->'steps') - 1 loop
insert into public.recipe_steps(recipe_id, position, body) values (rid, i + 1, r->'steps'->>i);
end loop;
end loop;
end $seed$;
select count(*) as published_recipes from public.curated_recipes where status = 'published';